from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.63.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.63.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
APP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.63.0.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.63.0.css').read_text()
COMPAT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-browser-compatibility-v1.js').read_text()
COMPATUI=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-browser-compatibility-ui-v1.js').read_text()
INTEGRITY=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-persistence-integrity-v1.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
def check(ok,label):
    if not ok: raise SystemExit('FAIL - '+label)
check('Version: 0.63.0' in MAIN and "SC_WORKSPACE_VERSION', '0.63.0" in MAIN,'plugin version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.63.0','0.62.0','Cross-Browser & Device Compatibility'),'release lineage')
check(MAN['storage_schema_version']==35 and MAN['project_schema']=='sc-workspace-project/20.0' and MAN['schema_migration_required'] is False,'schema stable')
check('/wp-json/sc-workspace/v1/compatibility-contract' in MAN['rest_routes'],'compatibility REST manifest')
check("'/compatibility-contract'" in PHP and 'compatibility_contract' in PHP,'compatibility REST implementation')
check('data-scw-workspace-view="compatibility"' in PHP and 'data-scw-browser-compatibility' in PHP,'Compatibility UI route')
check("SCHEMA='sc-workspace-browser-compatibility/1.0'" in COMPAT and "MATRIX_SCHEMA='sc-workspace-browser-compatibility-matrix/1.0'" in COMPAT and "REPORT_SCHEMA='sc-workspace-browser-compatibility-report/1.0'" in COMPAT,'compatibility schemas')
check("fileText?'file-text':fileReader?'file-reader':'unavailable'" in COMPAT and 'readFileText(file' in COMPAT,'file reader fallback')
check("mode:(blob&&objectUrl&&anchorDownload)?'object-url':anchorDownload?'data-uri-fallback':'unavailable'" in COMPAT and 'MAX_DATA_URI_BYTES=1024*1024' in COMPAT,'download fallback')
check("mode:'in-app-only'" in COMPAT and 'safeHistory' in COMPAT,'history fallback')
check('applyViewport' in COMPAT and 'ResizeObserver' in COMPAT and '--scw-viewport-height' in COMPAT,'root-bound viewport adapter')
check('rawUserAgentIncluded:false' in COMPAT and 'deviceIdentifierIncluded:false' in COMPAT and 'userAgentGating:false' in COMPAT,'privacy and feature-detection boundary')
check(APP.count('await readFileTextCompat(file)')>=8 and 'SCWorkspaceBrowserCompatibility' in APP,'application import integration')
check('downloadJson(filename,payload,window)' in APP and 'downloadText(filename,String(text || \'\'),type,window)' in APP,'application export integration')
aux_names=['sc-workspace-institutional-research-packages-ui-v1.js','sc-workspace-shared-review-handoff-ui-v1.js','sc-workspace-research-automation-ui-v1.js','sc-workspace-security-privacy-ui-v1.js','sc-workspace-field-diagnostics-v1.js','sc-workspace-public-beta-ii-ui-v1.js','sc-workspace-api-embed-ui-v1.js']
aux='\n'.join((ROOT/'wordpress/sustainable-catalyst-workspace/assets/js'/n).read_text() for n in aux_names)
check(aux.count('SCWorkspaceBrowserCompatibility')>=7 and 'readFileText(f,window)' in aux and ('downloadJson' in aux or 'downloadText' in aux),'secondary workflow compatibility integration')
check('compat.safeHistory(window,historyMode,state)' in (ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-field-resilience-ui-v1.js').read_text(),'history integration')
check("compatibility:'Compatibility'" in NAV and "'integrity','compatibility'" in NAV,'navigation map')
check('sc-workspace-browser-compatibility-v1.js' in PHP and 'sc-workspace-browser-compatibility-ui-v1.js' in PHP,'compatibility assets enqueued')
check('workspace-v0.63.0.js' in PHP and 'workspace-v0.63.0.css' in PHP and len(APP)>100000,'current assets')
check('.scw-browser-compatibility{border-top:4px solid #000' in CSS and 'data-scw-device-class' in CSS,'compatibility CSS')
check("METADATA_KEY='sc_workspace_persistence_integrity_v0620'" in INTEGRITY and "TRANSACTION_KEY='sc_workspace_persistence_txn_v0620'" in INTEGRITY,'v0.62 integrity stores preserved')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0630'" in REGPHP and 'LEGACY_PENDING_KEY_V0620' in REGPHP,'registry recovery')
check(REG['public_version']=='0.63.0' and REG['previous_version']=='0.62.0','registry record')
for n in ['sc-workspace-browser-compatibility-v1.schema.json','sc-workspace-browser-compatibility-matrix-v1.schema.json','sc-workspace-browser-compatibility-report-v1.schema.json']:
    json.loads((ROOT/'schemas'/n).read_text())
check((ROOT/'history/release-manifest-v0.62.0.json').exists() and (ROOT/'history/workspace-product-record-v0.62.0.json').exists(),'predecessor history')
check(MAN['cross_browser_device_compatibility']['manual_qa_required'] is True and MAN['cross_browser_device_compatibility']['browser_family_feature_gating'] is False,'manual QA claim boundary')
check(PHP.count('A free project environment for carrying questions, evidence, data, analysis, decisions, and authored work across Sustainable Catalyst.')==1,'duplicate hero deck remains removed')
print('PASS - v0.63.0 release validator')
